def global_aligned(D, mark, groups_r, groups_c, hr, wc):
    marks=[(r,c) for r in range(D.shape[0]) for c in range(D.shape[1]) if D[r,c]==mark]
    res={}
    for ri,r0 in enumerate(groups_r):
        for ci,c0 in enumerate(groups_c):
            blk=[(r,c) for r,c in marks if r0<=r<r0+hr and c0<=c<c0+wc]
            n=sum(1 for r,c in blk if any((r2==r or c2==c) for r2,c2 in marks if (r2,c2)!=(r,c)))
            res[(ri,ci)]=(len(blk),n)
    return res
