def lines_analysis(D, mark, gr, gc, hr, wc, out):
    marks=[(r,c) for r in range(D.shape[0]) for c in range(D.shape[1]) if D[r,c]==mark]
    # for each column, group marks into runs (consecutive rows)
    colmarks=collections.defaultdict(list)
    for r,c in marks: colmarks[c].append(r)
    # global columns having a mark-run that spans >=2 blocks (run rows in different row-groups)
    linecols=set()
    for c,rs in colmarks.items():
        blkset={ri for ri,r0 in enumerate(gr) if any(r0<=r<r0+hr for r in rs)}
        if len(blkset)>=2: linecols.add(c)
    rowmarks=collections.defaultdict(list)
    for r,c in marks: rowmarks[r].append(c)
    linerows=set()
    for r,cs in rowmarks.items():
        blkset={ci for ci,c0 in enumerate(gc) if any(c0<=c<c0+wc for c in cs)}
        if len(blkset)>=2: linerows.add(r)
    print("linecols",sorted(linecols),"linerows",sorted(linerows))
    for ri,r0 in enumerate(gr):
        row=[]
        for ci,c0 in enumerate(gc):
            n=sum(1 for r,c in marks if r0<=r<r0+hr and c0<=c<c0+wc and (c in linecols or r in linerows))
            row.append(n)
        print(row, "out", out[ri])
