import itertools
def feats(D, mark, gr, gc, hr, wc):
    marks=[(r,c) for r in range(D.shape[0]) for c in range(D.shape[1]) if D[r,c]==mark]
    F={}
    for ri,r0 in enumerate(gr):
        for ci,c0 in enumerate(gc):
            blk=[(r-r0,c-c0) for r,c in marks if r0<=r<r0+hr and c0<=c<c0+wc]
            n=len(blk)
            cols=sorted(set(c for r,c in blk)); rows=sorted(set(r for r,c in blk))
            gap_col=any(any(b-a>=2 for a,b in zip(sorted(r for r,c in blk if c==cc), sorted(r for r,c in blk if c==cc)[1:])) for cc in cols)
            f={'n':n,'samecol':len(cols)<n,'samerow':len(rows)<n,'gapcol':gap_col,
               'minc':min(cols) if cols else -1,'maxc':max(cols) if cols else -1,
               'minr':min(rows) if rows else -1,'maxr':max(rows) if rows else -1,
               'sumr':sum(r for r,c in blk),'sumc':sum(c for r,c in blk)}
            # group totals
            gt_r=sum(1 for r,c in marks if gr[ri]<=r<gr[ri]+hr)
            gt_c=sum(1 for r,c in marks if gc[ci]<=c<gc[ci]+wc)
            f['gt_rowgroup']=gt_r; f['gt_colgroup']=gt_c
            F[(ri,ci)]=f
    return F
