from collections import Counter
def allfeats(D, mark, gr, gc):
    marks=[(r,c) for r in range(D.shape[0]) for c in range(D.shape[1]) if D[r,c]==mark]
    B={}
    for ri,r0 in enumerate(gr):
        for ci,c0 in enumerate(gc):
            B[(ri,ci)]=[(r-r0,c-c0) for r,c in marks if r0<=r<r0+ (gr[1]-gr[0]-1) and c0<=c<c0+(gc[1]-gc[0]-1)]
    hr=gr[1]-gr[0]-1; wc=gc[1]-gc[0]-1
    nrg=len(gr); ncg=len(gc)
    colcnt=Counter(c for r,c in marks); rowcnt=Counter(r for r,c in marks)
    # rel col counts per colgroup, rel row counts per rowgroup, global rel counts
    cgcnt={ci:Counter() for ci in range(ncg)}
    rgcnt={ri:Counter() for ri in range(nrg)}
    grelc=Counter(); grelr=Counter()
    for (ri,ci),blk in B.items():
        for r,c in blk:
            cgcnt[ci][c]+=1; rgcnt[ri][r]+=1; grelc[c]+=1; grelr[r]+=1
    F={}
    for k,blk in B.items():
        ri,ci=k; n=len(blk)
        f=dict(n=n)
        if n:
            f['cgmin']=min(cgcnt[ci][c] for r,c in blk); f['cgmax']=max(cgcnt[ci][c] for r,c in blk)
            f['cgsum']=sum(cgcnt[ci][c] for r,c in blk)
            f['rgmin']=min(rgcnt[ri][r] for r,c in blk); f['rgmax']=max(rgcnt[ri][r] for r,c in blk)
            f['rgsum']=sum(rgcnt[ri][r] for r,c in blk)
            f['grelc']=grelc[blk[0][1]]; f['grelr']=grelr[blk[0][0]]
            f['colc']=sum(colcnt[gc[ci]+c] for r,c in blk)
            f['rowc']=sum(rowcnt[gr[ri]+r] for r,c in blk)
            # same rel col count across ALL colgroups (global pattern count)
            adj=0; gap=0
            for c in set(c2 for r2,c2 in blk):
                rs=sorted(r2 for r3,c3 in blk if c3==c for r2 in [r3])
                for a,b in zip(rs,rs[1:]):
                    if b-a==1: adj+=1
                    else: gap+=1
            f['adj']=adj; f['gap']=gap; f['hasgap']=int(gap>0)
        else:
            for kk in ['cgmin','cgmax','cgsum','rgmin','rgmax','rgsum','grelc','grelr','colc','rowc','adj','gap','hasgap']:
                f[kk]=0
        F[k]=f
    return F,B
